var FORTUNES=['今日宜冒险，忌犹豫。','贵人就在你忽略的角落。','慢一点，答案会自己浮现。','你种下的因，正在悄悄发芽。','一次失败只是剧情需要。','远方有人正想起你。','今天适合整理与清零。','你的耐心比想象中值钱。','意外的好消息正在路上。','相信直觉，它很少骗你。','把大事拆小，立刻开始。','好运偏爱有准备的人。','今天的你比昨天更聪明。','别怕重新开始，地图是画出来的。','微笑是最好的运气符。','一个决定会撬动整周。','安静的努力终将被看见。','给旧物一次新生命。','说出口的愿望更容易实现。','今晚适合早点睡。'];
function fortune(){return FORTUNES[Math.floor(Math.random()*FORTUNES.length)];}
var EXPORTS={fortune:fortune,FORTUNES:FORTUNES};


if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.FortuneForgePure = EXPORTS; }
